use crate::remote::auth::{DeviceInfo, DevicePermission};
use crate::remote::protocol::RemoteActiveDesktopSelection;
use crate::remote::state::{RemoteGatewayConfig, RemoteNetworkMode};
use crate::session::PersistedWorkspaceSession;
use crate::terminal::output_hub::ReplayGap;
use crate::terminal::TerminalSignal;
use crate::worktree::WorktreeIdentity;
use serde::{Deserialize, Serialize};
use std::borrow::Cow;

pub const DAEMON_PROTOCOL_VERSION: u32 = 2;

pub mod base64_serde {
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    use serde::{de::Error as _, Deserialize, Deserializer, Serializer};
    use std::borrow::Cow;

    pub fn serialize<S, T>(bytes: &T, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
        T: AsRef<[u8]>,
    {
        serializer.serialize_str(&STANDARD.encode(bytes.as_ref()))
    }

    pub fn deserialize<'de, D, T>(deserializer: D) -> Result<T, D::Error>
    where
        D: Deserializer<'de>,
        T: From<Vec<u8>>,
    {
        let s = Cow::<'de, str>::deserialize(deserializer)?;
        let decoded = STANDARD.decode(s.as_bytes()).map_err(D::Error::custom)?;
        Ok(T::from(decoded))
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DaemonSessionDetails {
    pub session_id: String,
    pub workspace_id: Option<String>,
    pub worktree: Option<WorktreeIdentity>,
    pub cwd: Option<String>,
    pub cols: u16,
    pub rows: u16,
    pub running: bool,
    pub start_sequence: Option<u64>,
    pub end_sequence: Option<u64>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DaemonRemoteStatus {
    pub mode: RemoteNetworkMode,
    pub port: u16,
    pub allow_control: bool,
    pub is_running: bool,
    pub bound_address: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonRequest {
    #[serde(rename_all = "camelCase")]
    Handshake {
        version: u32,
    },
    Ping,
    #[serde(rename_all = "camelCase")]
    RegisterWorkspace {
        workspace_id: String,
        repo_root: String,
    },
    #[serde(rename_all = "camelCase")]
    Spawn {
        client_request_id: String,
        workspace_id: String,
        worktree: Option<WorktreeIdentity>,
        cwd: Option<String>,
        cols: u16,
        rows: u16,
    },
    #[serde(rename_all = "camelCase")]
    Write {
        session_id: String,
        #[serde(with = "base64_serde")]
        data: Vec<u8>,
    },
    #[serde(rename_all = "camelCase")]
    Resize {
        session_id: String,
        cols: u16,
        rows: u16,
    },
    #[serde(rename_all = "camelCase")]
    Signal {
        session_id: String,
        signal: TerminalSignal,
    },
    #[serde(rename_all = "camelCase")]
    Close {
        session_id: String,
    },
    ListSessions,
    #[serde(rename_all = "camelCase")]
    DescribeSession {
        session_id: String,
    },
    #[serde(rename_all = "camelCase")]
    Attach {
        session_id: String,
        after_sequence: Option<u64>,
    },
    #[serde(rename_all = "camelCase")]
    SaveSession {
        session: PersistedWorkspaceSession,
    },
    LoadSession,
    ClearSession,
    RemoteGetStatus,
    #[serde(rename_all = "camelCase")]
    RemoteConfigure {
        config: RemoteGatewayConfig,
    },
    #[serde(rename_all = "camelCase")]
    RemoteCreatePairingCode {
        permission: Option<DevicePermission>,
    },
    RemoteListDevices,
    #[serde(rename_all = "camelCase")]
    RemoteRevokeDevice {
        device_id: String,
    },
    #[serde(rename_all = "camelCase")]
    RemoteSetActiveSelection {
        selection: Option<RemoteActiveDesktopSelection>,
    },
    RemoteGetActiveSelection,
    Shutdown,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonResponse {
    #[serde(rename_all = "camelCase")]
    HandshakeOk {
        version: u32,
        pid: u32,
        epoch: u64,
    },
    Pong,
    RegisterWorkspaceOk,
    #[serde(rename_all = "camelCase")]
    SpawnOk {
        session_id: String,
    },
    WriteOk,
    ResizeOk,
    SignalOk,
    CloseOk,
    #[serde(rename_all = "camelCase")]
    ListSessionsOk {
        epoch: u64,
        sessions: Vec<String>,
    },
    #[serde(rename_all = "camelCase")]
    DescribeSessionOk {
        session: DaemonSessionDetails,
    },
    #[serde(rename_all = "camelCase")]
    AttachOk {
        epoch: u64,
        session_id: String,
        start_sequence: Option<u64>,
        end_sequence: Option<u64>,
        gap: Option<ReplayGap>,
        #[serde(with = "base64_serde")]
        history: Vec<u8>,
    },
    SaveSessionOk,
    #[serde(rename_all = "camelCase")]
    LoadSessionOk {
        session: Option<PersistedWorkspaceSession>,
    },
    ClearSessionOk,
    #[serde(rename_all = "camelCase")]
    RemoteStatusOk {
        status: DaemonRemoteStatus,
    },
    RemoteConfigureOk,
    #[serde(rename_all = "camelCase")]
    RemotePairingCodeOk {
        code: String,
    },
    #[serde(rename_all = "camelCase")]
    RemoteListDevicesOk {
        devices: Vec<DeviceInfo>,
    },
    RemoteRevokeDeviceOk,
    RemoteSetActiveSelectionOk,
    #[serde(rename_all = "camelCase")]
    RemoteGetActiveSelectionOk {
        selection: Option<RemoteActiveDesktopSelection>,
    },
    #[serde(rename_all = "camelCase")]
    Error {
        message: String,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum DaemonStreamMessage<'a> {
    #[serde(rename_all = "camelCase")]
    Output {
        session_id: Cow<'a, str>,
        sequence: u64,
        #[serde(with = "base64_serde")]
        data: Cow<'a, [u8]>,
    },
    #[serde(rename_all = "camelCase")]
    Gap {
        session_id: Cow<'a, str>,
        requested_after_sequence: u64,
        available_from_sequence: u64,
    },
    #[serde(rename_all = "camelCase")]
    Lagged {
        session_id: Cow<'a, str>,
        start_sequence: Option<u64>,
        end_sequence: Option<u64>,
        gap: Option<ReplayGap>,
        #[serde(with = "base64_serde")]
        history: Cow<'a, [u8]>,
    },
    #[serde(rename_all = "camelCase")]
    Exit {
        session_id: Cow<'a, str>,
        exit_code: Option<i32>,
    },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_daemon_stream_message_compact_base64_encoding() {
        let output = DaemonStreamMessage::Output {
            session_id: Cow::Borrowed("s1"),
            sequence: 42,
            data: Cow::Borrowed(b"hello world"),
        };
        let json = serde_json::to_string(&output).expect("serialize output");

        assert!(
            !json.contains('['),
            "Stream output must not contain JSON number arrays: {json}"
        );
        assert!(
            json.contains(r#""data":"aGVsbG8gd29ybGQ=""#),
            "Expected base64-encoded string for data: {json}"
        );
        assert!(
            json.contains(r#""sessionId":"s1""#),
            "Expected camelCase sessionId: {json}"
        );
        assert!(
            json.contains(r#""sequence":42"#),
            "Expected sequence 42: {json}"
        );

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize output");
        match deserialized {
            DaemonStreamMessage::Output {
                session_id,
                sequence,
                data,
            } => {
                assert_eq!(session_id, "s1");
                assert_eq!(sequence, 42);
                assert_eq!(&data[..], b"hello world");
            }
            _ => panic!("Expected Output variant"),
        }
    }

    #[test]
    fn test_daemon_stream_message_gap_roundtrip() {
        let gap = DaemonStreamMessage::Gap {
            session_id: Cow::Borrowed("s_gap"),
            requested_after_sequence: 10,
            available_from_sequence: 50,
        };
        let json = serde_json::to_string(&gap).expect("serialize gap");
        assert!(json.contains(r#""type":"gap""#));
        assert!(json.contains(r#""sessionId":"s_gap""#));
        assert!(json.contains(r#""requestedAfterSequence":10"#));
        assert!(json.contains(r#""availableFromSequence":50"#));

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize gap");
        assert_eq!(
            deserialized,
            DaemonStreamMessage::Gap {
                session_id: Cow::Owned("s_gap".to_string()),
                requested_after_sequence: 10,
                available_from_sequence: 50,
            }
        );
    }

    #[test]
    fn test_daemon_stream_message_lagged_with_replay_gap_roundtrip() {
        let replay_gap = ReplayGap {
            requested_after_sequence: 10,
            available_from_sequence: 35,
        };
        let lagged = DaemonStreamMessage::Lagged {
            session_id: Cow::Borrowed("s2"),
            start_sequence: Some(35),
            end_sequence: Some(100),
            gap: Some(replay_gap.clone()),
            history: Cow::Borrowed(b"history bytes"),
        };
        let json = serde_json::to_string(&lagged).expect("serialize lagged");
        assert!(!json.contains('['));
        assert!(json.contains(r#""history":"aGlzdG9yeSBieXRlcw==""#));
        assert!(json.contains(r#""sessionId":"s2""#));
        assert!(json.contains(r#""startSequence":35"#));
        assert!(json.contains(r#""endSequence":100"#));
        assert!(
            json.contains(r#""gap":{"requested_after_sequence":10,"available_from_sequence":35}"#)
        );

        let deserialized: DaemonStreamMessage =
            serde_json::from_str(&json).expect("deserialize lagged");
        assert_eq!(
            deserialized,
            DaemonStreamMessage::Lagged {
                session_id: Cow::Owned("s2".to_string()),
                start_sequence: Some(35),
                end_sequence: Some(100),
                gap: Some(replay_gap),
                history: Cow::Owned(b"history bytes".to_vec()),
            }
        );
    }

    #[test]
    fn test_register_workspace_and_remote_commands_serde() {
        let reg_req = DaemonRequest::RegisterWorkspace {
            workspace_id: "ws-123".to_string(),
            repo_root: "/path/to/repo".to_string(),
        };
        let reg_json = serde_json::to_string(&reg_req).expect("serialize register");
        assert!(reg_json.contains(r#""workspaceId":"ws-123""#));
        assert!(reg_json.contains(r#""repoRoot":"/path/to/repo""#));

        let remote_status_resp = DaemonResponse::RemoteStatusOk {
            status: DaemonRemoteStatus {
                mode: RemoteNetworkMode::LocalNetwork,
                port: 43821,
                allow_control: true,
                is_running: true,
                bound_address: Some("0.0.0.0:43821".to_string()),
            },
        };
        let status_json = serde_json::to_string(&remote_status_resp).expect("serialize status");
        assert!(status_json.contains(r#""isRunning":true"#));
        assert!(status_json.contains(r#""boundAddress":"0.0.0.0:43821""#));

        let pair_resp = DaemonResponse::RemotePairingCodeOk {
            code: "123456".to_string(),
        };
        let pair_json = serde_json::to_string(&pair_resp).expect("serialize pair code");
        assert!(pair_json.contains(r#""code":"123456""#));
    }

    #[test]
    fn test_daemon_request_write_and_response_attach_base64() {
        let write_req = DaemonRequest::Write {
            session_id: "term-1".to_string(),
            data: b"ls -la\n".to_vec(),
        };
        let json = serde_json::to_string(&write_req).expect("serialize write");
        assert!(!json.contains('['));
        assert!(json.contains(r#""data":"bHMgLWxhCg==""#));
        assert!(json.contains(r#""sessionId":"term-1""#));

        let deserialized_req: DaemonRequest =
            serde_json::from_str(&json).expect("deserialize write");
        match deserialized_req {
            DaemonRequest::Write { session_id, data } => {
                assert_eq!(session_id, "term-1");
                assert_eq!(data, b"ls -la\n");
            }
            _ => panic!("Expected Write variant"),
        }

        let attach_resp = DaemonResponse::AttachOk {
            epoch: 12345,
            session_id: "term-1".to_string(),
            start_sequence: Some(1),
            end_sequence: Some(10),
            gap: None,
            history: b"initial prompt $ ".to_vec(),
        };
        let resp_json = serde_json::to_string(&attach_resp).expect("serialize attach resp");
        assert!(!resp_json.contains('['));
        assert!(resp_json.contains(r#""history":"aW5pdGlhbCBwcm9tcHQgJCA=""#));
        assert!(resp_json.contains(r#""epoch":12345"#));
        assert!(resp_json.contains(r#""sessionId":"term-1""#));

        let deserialized_resp: DaemonResponse =
            serde_json::from_str(&resp_json).expect("deserialize attach resp");
        match deserialized_resp {
            DaemonResponse::AttachOk {
                epoch,
                session_id,
                start_sequence,
                end_sequence,
                gap,
                history,
            } => {
                assert_eq!(epoch, 12345);
                assert_eq!(session_id, "term-1");
                assert_eq!(start_sequence, Some(1));
                assert_eq!(end_sequence, Some(10));
                assert!(gap.is_none());
                assert_eq!(history, b"initial prompt $ ");
            }
            _ => panic!("Expected AttachOk variant"),
        }
    }

    #[test]
    fn test_describe_session_and_spawn_v2_serde() {
        let spawn_req = DaemonRequest::Spawn {
            client_request_id: "req-abc-123".to_string(),
            workspace_id: "default".to_string(),
            worktree: None,
            cwd: Some("/tmp/test-cwd".to_string()),
            cols: 120,
            rows: 40,
        };
        let spawn_json = serde_json::to_string(&spawn_req).expect("serialize spawn");
        assert!(spawn_json.contains(r#""clientRequestId":"req-abc-123""#));
        assert!(spawn_json.contains(r#""cwd":"/tmp/test-cwd""#));

        let describe_req = DaemonRequest::DescribeSession {
            session_id: "session-99".to_string(),
        };
        let desc_json = serde_json::to_string(&describe_req).expect("serialize describe");
        assert!(desc_json.contains(r#""sessionId":"session-99""#));

        let desc_resp = DaemonResponse::DescribeSessionOk {
            session: DaemonSessionDetails {
                session_id: "session-99".to_string(),
                workspace_id: Some("default".to_string()),
                worktree: None,
                cwd: Some("/tmp/test-cwd".to_string()),
                cols: 120,
                rows: 40,
                running: true,
                start_sequence: Some(5),
                end_sequence: Some(50),
            },
        };
        let desc_resp_json = serde_json::to_string(&desc_resp).expect("serialize describe resp");
        assert!(desc_resp_json.contains(r#""running":true"#));
        assert!(desc_resp_json.contains(r#""startSequence":5"#));
    }

    #[test]
    fn test_protocol_v2_handshake_and_list_sessions_epoch() {
        assert_eq!(DAEMON_PROTOCOL_VERSION, 2);

        let hs = DaemonResponse::HandshakeOk {
            version: DAEMON_PROTOCOL_VERSION,
            pid: 9999,
            epoch: 777777,
        };
        let hs_json = serde_json::to_string(&hs).expect("serialize handshake");
        assert!(hs_json.contains(r#""epoch":777777"#));
        assert!(hs_json.contains(r#""version":2"#));

        let list = DaemonResponse::ListSessionsOk {
            epoch: 777777,
            sessions: vec!["s1".to_string(), "s2".to_string()],
        };
        let list_json = serde_json::to_string(&list).expect("serialize list");
        assert!(list_json.contains(r#""epoch":777777"#));
    }
}

// allow: SIZE_OK — daemon IPC server implementation with routing, session persistence offloading, remote control, and streaming
use crate::daemon::protocol::{
    DaemonRemoteStatus, DaemonRequest, DaemonResponse, DaemonSessionDetails, DaemonStreamMessage,
    DAEMON_PROTOCOL_VERSION,
};
use crate::remote::auth::DevicePermission;
use crate::remote::server::{start_remote_server, RemoteServerHandle};
use crate::remote::state::{RemoteGatewayConfig, RemoteGatewayState, RemoteNetworkMode};
use crate::session::{clear_session_from_path, load_session_from_path, save_session_to_path};
use crate::terminal::{PtyManager, PtySessionState, TerminalOutputHub, TerminalService};
use crate::worktree::{WorkspaceRegistry, WorktreeIdentity};
use parking_lot::{Mutex, RwLock};
use portable_pty::CommandBuilder;
use std::borrow::Cow;
use std::collections::HashMap;
use std::fs::{self, OpenOptions};
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader, BufWriter};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::broadcast;

pub fn get_runtime_dir() -> PathBuf {
    let uid = unsafe { libc::getuid() };
    let path = PathBuf::from(format!("/tmp/rorca-{uid}"));

    if fs::symlink_metadata(&path).is_ok() {
        if let Ok(meta) = fs::symlink_metadata(&path) {
            if meta.file_type().is_symlink() || meta.uid() != uid || !meta.file_type().is_dir() {
                let _ = fs::remove_file(&path);
                let _ = fs::remove_dir_all(&path);
            }
        }
    }

    let _ = fs::create_dir_all(&path);
    if let Ok(metadata) = fs::symlink_metadata(&path) {
        let mut permissions = metadata.permissions();
        permissions.set_mode(0o700);
        let _ = fs::set_permissions(&path, permissions);
    }
    path
}

pub fn get_socket_path() -> PathBuf {
    get_runtime_dir().join("daemon.sock")
}

pub fn get_lock_path() -> PathBuf {
    get_runtime_dir().join("daemon.lock")
}

pub fn get_default_session_path() -> PathBuf {
    if let Some(mut base) = dirs_next().or_else(dirs_fallback) {
        base.push("rorca");
        let _ = fs::create_dir_all(&base);
        base.join("session_state.json")
    } else {
        get_runtime_dir().join("session_state.json")
    }
}

fn dirs_next() -> Option<PathBuf> {
    #[cfg(target_os = "macos")]
    {
        std::env::var_os("HOME").map(|h| PathBuf::from(h).join("Library/Application Support"))
    }
    #[cfg(not(target_os = "macos"))]
    {
        std::env::var_os("XDG_DATA_HOME")
            .map(PathBuf::from)
            .or_else(|| std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".local/share")))
    }
}

fn dirs_fallback() -> Option<PathBuf> {
    std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".rorca"))
}

fn validate_safe_ownership_and_type(path: &Path, expect_dir: bool) -> Result<(), String> {
    let meta = fs::symlink_metadata(path)
        .map_err(|e| format!("Failed to read metadata for {}: {e}", path.display()))?;
    if meta.file_type().is_symlink() {
        return Err(format!(
            "Path {} is a symlink, which is prohibited for daemon runtime",
            path.display()
        ));
    }
    let uid = unsafe { libc::getuid() };
    if meta.uid() != uid {
        return Err(format!(
            "Path {} is owned by UID {} (expected current UID {})",
            path.display(),
            meta.uid(),
            uid
        ));
    }
    if expect_dir && !meta.file_type().is_dir() {
        return Err(format!("Path {} is not a directory", path.display()));
    }
    Ok(())
}

#[derive(Clone)]
struct StoredSessionMeta {
    workspace_id: String,
    worktree: Option<WorktreeIdentity>,
    cwd: PathBuf,
}

pub struct DaemonServer {
    terminal_service: Arc<TerminalService>,
    workspace_registry: WorkspaceRegistry,
    remote_state: Arc<RemoteGatewayState>,
    remote_server_handle: Arc<Mutex<Option<RemoteServerHandle>>>,
    epoch: u64,
    spawn_idempotency_cache: Arc<RwLock<HashMap<String, String>>>,
    session_metadata: Arc<RwLock<HashMap<String, StoredSessionMeta>>>,
}

impl Default for DaemonServer {
    fn default() -> Self {
        Self::new()
    }
}

impl DaemonServer {
    pub fn new() -> Self {
        let pty_manager = Arc::new(PtyManager::new());
        let output_hub = Arc::new(TerminalOutputHub::default());
        let terminal_service = Arc::new(TerminalService::new(
            Arc::clone(&pty_manager),
            Arc::clone(&output_hub),
        ));
        let workspace_registry = WorkspaceRegistry::new();
        let remote_state = Arc::new(RemoteGatewayState::new(
            Arc::clone(&terminal_service),
            workspace_registry.clone(),
        ));

        // Remote gateway is OFF by default; daemon listener is not started until explicitly configured
        *remote_state.config.write() = RemoteGatewayConfig {
            mode: RemoteNetworkMode::Off,
            port: 43821,
            allow_control: true,
        };

        let epoch = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_millis() as u64)
            .unwrap_or(1);

        Self {
            terminal_service,
            workspace_registry,
            remote_state,
            remote_server_handle: Arc::new(Mutex::new(None)),
            epoch,
            spawn_idempotency_cache: Arc::new(RwLock::new(HashMap::new())),
            session_metadata: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    pub fn epoch(&self) -> u64 {
        self.epoch
    }

    pub fn terminal_service(&self) -> &Arc<TerminalService> {
        &self.terminal_service
    }

    pub fn workspace_registry(&self) -> &WorkspaceRegistry {
        &self.workspace_registry
    }

    pub fn remote_state(&self) -> &Arc<RemoteGatewayState> {
        &self.remote_state
    }

    pub async fn run_server(self: Arc<Self>) -> Result<(), String> {
        let runtime_dir = get_runtime_dir();
        validate_safe_ownership_and_type(&runtime_dir, true)?;

        let socket_path = get_socket_path();
        let lock_path = get_lock_path();

        if lock_path.exists() || fs::symlink_metadata(&lock_path).is_ok() {
            validate_safe_ownership_and_type(&lock_path, false)?;
        }

        // Flock lock for atomic bind & stale socket recovery
        let lock_file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(&lock_path)
            .map_err(|e| format!("Failed to open lock file: {e}"))?;

        unsafe {
            use std::os::unix::io::AsRawFd;
            let fd = lock_file.as_raw_fd();
            if libc::flock(fd, libc::LOCK_EX | libc::LOCK_NB) != 0 {
                return Err("Another daemon instance is already holding the lock.".into());
            }
        }

        // Clean up stale socket only after lock acquisition and safe ownership check
        if socket_path.exists() || fs::symlink_metadata(&socket_path).is_ok() {
            validate_safe_ownership_and_type(&socket_path, false)?;
            let _ = fs::remove_file(&socket_path);
        }

        let listener = UnixListener::bind(&socket_path).map_err(|e| {
            format!(
                "Failed to bind UDS socket at {}: {e}",
                socket_path.display()
            )
        })?;

        // Ensure 0600 mode
        if let Ok(metadata) = fs::symlink_metadata(&socket_path) {
            let mut permissions = metadata.permissions();
            permissions.set_mode(0o600);
            let _ = fs::set_permissions(&socket_path, permissions);
        }

        tracing::info!("rorca daemon listening on {}", socket_path.display());

        loop {
            match listener.accept().await {
                Ok((stream, _)) => {
                    let server = Arc::clone(&self);
                    tokio::spawn(async move {
                        server.handle_client(stream).await;
                    });
                }
                Err(e) => {
                    tracing::error!("Daemon accept error: {e}");
                    break;
                }
            }
        }

        Ok(())
    }

    pub async fn handle_client(self: Arc<Self>, stream: UnixStream) {
        let (read_half, mut write_half) = stream.into_split();
        let mut reader = BufReader::new(read_half);
        let mut line = String::new();

        while let Ok(n) = reader.read_line(&mut line).await {
            if n == 0 {
                break;
            }
            let req: Result<DaemonRequest, _> = serde_json::from_str(line.trim());
            line.clear();

            let resp = match req {
                Ok(DaemonRequest::Handshake { version }) => {
                    if version != DAEMON_PROTOCOL_VERSION {
                        DaemonResponse::Error {
                            message: format!(
                                "Protocol version mismatch: expected {DAEMON_PROTOCOL_VERSION}, got {version}"
                            ),
                        }
                    } else {
                        DaemonResponse::HandshakeOk {
                            version: DAEMON_PROTOCOL_VERSION,
                            pid: std::process::id(),
                            epoch: self.epoch,
                        }
                    }
                }
                Ok(DaemonRequest::Ping) => DaemonResponse::Pong,
                Ok(DaemonRequest::RegisterWorkspace {
                    workspace_id,
                    repo_root,
                }) => match self.handle_register_workspace(&workspace_id, &repo_root) {
                    Ok(()) => DaemonResponse::RegisterWorkspaceOk,
                    Err(e) => DaemonResponse::Error { message: e },
                },
                Ok(DaemonRequest::Spawn {
                    client_request_id,
                    workspace_id,
                    worktree,
                    cwd,
                    cols,
                    rows,
                }) => {
                    let res = self
                        .handle_spawn(&client_request_id, &workspace_id, worktree, cwd, cols, rows)
                        .await;
                    match res {
                        Ok(session_id) => DaemonResponse::SpawnOk { session_id },
                        Err(e) => DaemonResponse::Error { message: e },
                    }
                }
                Ok(DaemonRequest::DescribeSession { session_id }) => {
                    self.handle_describe_session(&session_id)
                }
                Ok(DaemonRequest::Write { session_id, data }) => {
                    match self.terminal_service.write_input(&session_id, &data) {
                        Ok(()) => DaemonResponse::WriteOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::Resize {
                    session_id,
                    cols,
                    rows,
                }) => match self.terminal_service.resize(&session_id, cols, rows) {
                    Ok(()) => DaemonResponse::ResizeOk,
                    Err(e) => DaemonResponse::Error {
                        message: e.to_string(),
                    },
                },
                Ok(DaemonRequest::Signal { session_id, signal }) => {
                    match self.terminal_service.signal(&session_id, signal) {
                        Ok(()) => DaemonResponse::SignalOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::Close { session_id }) => {
                    self.session_metadata.write().remove(&session_id);
                    match self.terminal_service.close_session(&session_id).await {
                        Ok(()) => DaemonResponse::CloseOk,
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::ListSessions) => {
                    let sessions = self.terminal_service.list_sessions();
                    DaemonResponse::ListSessionsOk {
                        epoch: self.epoch,
                        sessions,
                    }
                }
                Ok(DaemonRequest::Attach {
                    session_id,
                    after_sequence,
                }) => {
                    match self
                        .terminal_service
                        .attach_with_sequence(&session_id, after_sequence)
                    {
                        Ok(attachment) => {
                            let hub = Arc::clone(self.terminal_service.output_hub());
                            let resp = DaemonResponse::AttachOk {
                                epoch: self.epoch,
                                session_id: session_id.clone(),
                                start_sequence: attachment.snapshot.history_start_sequence,
                                end_sequence: attachment.snapshot.history_end_sequence,
                                gap: attachment.snapshot.gap,
                                history: attachment.snapshot.history,
                            };
                            let mut resp_json = serde_json::to_string(&resp).unwrap();
                            resp_json.push('\n');
                            let _ = write_half.write_all(resp_json.as_bytes()).await;
                            let _ = write_half.flush().await;

                            Self::pump_sequenced_stream(
                                session_id,
                                attachment.receiver,
                                hub,
                                write_half,
                            )
                            .await;
                            return;
                        }
                        Err(e) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                    }
                }
                Ok(DaemonRequest::SaveSession { session }) => {
                    let path = get_default_session_path();
                    let res =
                        tokio::task::spawn_blocking(move || save_session_to_path(&path, &session))
                            .await;
                    match res {
                        Ok(Ok(())) => DaemonResponse::SaveSessionOk,
                        Ok(Err(e)) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                        Err(e) => DaemonResponse::Error {
                            message: format!("Save session task panicked: {e}"),
                        },
                    }
                }
                Ok(DaemonRequest::LoadSession) => {
                    let path = get_default_session_path();
                    let res =
                        tokio::task::spawn_blocking(move || load_session_from_path(&path)).await;
                    match res {
                        Ok(Ok(session)) => DaemonResponse::LoadSessionOk { session },
                        Ok(Err(e)) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                        Err(e) => DaemonResponse::Error {
                            message: format!("Load session task panicked: {e}"),
                        },
                    }
                }
                Ok(DaemonRequest::ClearSession) => {
                    let path = get_default_session_path();
                    let res =
                        tokio::task::spawn_blocking(move || clear_session_from_path(&path)).await;
                    match res {
                        Ok(Ok(())) => DaemonResponse::ClearSessionOk,
                        Ok(Err(e)) => DaemonResponse::Error {
                            message: e.to_string(),
                        },
                        Err(e) => DaemonResponse::Error {
                            message: format!("Clear session task panicked: {e}"),
                        },
                    }
                }
                Ok(DaemonRequest::RemoteGetStatus) => {
                    let config = self.remote_state.config.read().clone();
                    let is_running = *self.remote_state.is_running.read();
                    let bound_address = self.remote_state.bound_address.read().clone();
                    DaemonResponse::RemoteStatusOk {
                        status: DaemonRemoteStatus {
                            mode: config.mode,
                            port: config.port,
                            allow_control: config.allow_control,
                            is_running,
                            bound_address,
                        },
                    }
                }
                Ok(DaemonRequest::RemoteConfigure { config }) => {
                    match self.handle_remote_configure(config).await {
                        Ok(()) => DaemonResponse::RemoteConfigureOk,
                        Err(e) => DaemonResponse::Error { message: e },
                    }
                }
                Ok(DaemonRequest::RemoteCreatePairingCode { permission }) => {
                    let perm = permission.unwrap_or(DevicePermission::Control);
                    let code = self.remote_state.auth_manager.create_pairing_code(perm);
                    DaemonResponse::RemotePairingCodeOk { code }
                }
                Ok(DaemonRequest::RemoteListDevices) => {
                    let devices = self.remote_state.auth_manager.list_devices();
                    DaemonResponse::RemoteListDevicesOk { devices }
                }
                Ok(DaemonRequest::RemoteRevokeDevice { device_id }) => {
                    if self.remote_state.auth_manager.revoke_device(&device_id) {
                        DaemonResponse::RemoteRevokeDeviceOk
                    } else {
                        DaemonResponse::Error {
                            message: format!("Device '{device_id}' not found or already revoked"),
                        }
                    }
                }
                Ok(DaemonRequest::RemoteSetActiveSelection { selection }) => {
                    *self.remote_state.active_selection.write() = selection;
                    DaemonResponse::RemoteSetActiveSelectionOk
                }
                Ok(DaemonRequest::RemoteGetActiveSelection) => {
                    let selection = self.remote_state.active_selection.read().clone();
                    DaemonResponse::RemoteGetActiveSelectionOk { selection }
                }
                Ok(DaemonRequest::Shutdown) => {
                    std::process::exit(0);
                }
                Err(e) => DaemonResponse::Error {
                    message: format!("Malformed request: {e}"),
                },
            };

            let mut resp_json = serde_json::to_string(&resp).unwrap();
            resp_json.push('\n');
            if write_half.write_all(resp_json.as_bytes()).await.is_err() {
                break;
            }
            let _ = write_half.flush().await;
        }
    }

    pub fn handle_register_workspace(
        &self,
        workspace_id: &str,
        repo_root: &str,
    ) -> Result<(), String> {
        let path = PathBuf::from(repo_root);
        let canonical = fs::canonicalize(&path)
            .map_err(|e| format!("Invalid repo_root path '{}': {e}", path.display()))?;
        if !canonical.is_dir() {
            return Err(format!(
                "Repo root '{}' is not a directory",
                canonical.display()
            ));
        }
        self.workspace_registry
            .register(workspace_id, &canonical)
            .map_err(|e| e.to_string())
    }

    pub async fn handle_remote_configure(&self, config: RemoteGatewayConfig) -> Result<(), String> {
        *self.remote_state.config.write() = config.clone();

        // Stop current running server if any
        let prev_handle = self.remote_server_handle.lock().take();
        if let Some(handle) = prev_handle {
            handle.stop();
        }

        match config.mode {
            RemoteNetworkMode::Off => Ok(()),
            _ => {
                let (handle, _) = start_remote_server(Arc::clone(&self.remote_state)).await?;
                *self.remote_server_handle.lock() = Some(handle);
                Ok(())
            }
        }
    }

    async fn handle_spawn(
        &self,
        client_request_id: &str,
        workspace_id: &str,
        worktree: Option<WorktreeIdentity>,
        cwd: Option<String>,
        cols: u16,
        rows: u16,
    ) -> Result<String, String> {
        // 1. Idempotency cache lookup
        {
            let cache = self.spawn_idempotency_cache.read();
            if let Some(existing_session_id) = cache.get(client_request_id) {
                if self
                    .terminal_service
                    .get_session(existing_session_id)
                    .is_some()
                {
                    return Ok(existing_session_id.clone());
                }
            }
        }

        // 2. Resolve manager from workspace registry; workspace MUST be registered
        let (mgr, default_cwd) = self
            .workspace_registry
            .resolve_terminal_target(workspace_id, worktree.as_ref())
            .map_err(|e| e.to_string())?;

        let resolved_cwd = if let Some(ref custom_cwd_str) = cwd {
            let custom_path = PathBuf::from(custom_cwd_str);
            if !custom_path.exists() {
                return Err(format!("CWD does not exist: {custom_cwd_str}"));
            }
            if !custom_path.is_dir() {
                return Err(format!("CWD is not a directory: {custom_cwd_str}"));
            }
            let canonical = fs::canonicalize(&custom_path)
                .map_err(|e| format!("Cannot canonicalize CWD {custom_cwd_str}: {e}"))?;
            mgr.canonical_allowed_path(&canonical)
                .map_err(|e| format!("CWD '{custom_cwd_str}' is outside workspace: {e}"))?
        } else {
            default_cwd
        };

        let mut cmd = CommandBuilder::new_default_prog();
        cmd.cwd(&resolved_cwd);

        let (session_id, _) = self
            .terminal_service
            .spawn_in_worktree(cmd, cols, rows, &mgr, &resolved_cwd)
            .map_err(|e| e.to_string())?;

        // 3. Store idempotency entry and session metadata
        self.spawn_idempotency_cache
            .write()
            .insert(client_request_id.to_string(), session_id.clone());
        self.session_metadata.write().insert(
            session_id.clone(),
            StoredSessionMeta {
                workspace_id: workspace_id.to_string(),
                worktree,
                cwd: resolved_cwd,
            },
        );

        Ok(session_id)
    }

    fn handle_describe_session(&self, session_id: &str) -> DaemonResponse {
        let Some(pty_session) = self.terminal_service.get_session(session_id) else {
            return DaemonResponse::Error {
                message: format!("Session '{session_id}' not found"),
            };
        };

        let (cols, rows) = pty_session.get_size();
        let running = matches!(
            pty_session.state(),
            PtySessionState::Starting | PtySessionState::Running
        );
        let (start_sequence, end_sequence) = self
            .terminal_service
            .output_hub()
            .session_sequence_range(session_id)
            .unwrap_or((None, None));

        let meta = self.session_metadata.read().get(session_id).cloned();
        let (workspace_id, worktree, cwd) = match meta {
            Some(m) => (
                Some(m.workspace_id),
                m.worktree,
                Some(m.cwd.to_string_lossy().to_string()),
            ),
            None => (
                None,
                None,
                pty_session
                    .worktree_path()
                    .map(|p| p.to_string_lossy().to_string()),
            ),
        };

        DaemonResponse::DescribeSessionOk {
            session: DaemonSessionDetails {
                session_id: session_id.to_string(),
                workspace_id,
                worktree,
                cwd,
                cols,
                rows,
                running,
                start_sequence,
                end_sequence,
            },
        }
    }

    pub async fn pump_sequenced_stream(
        session_id: String,
        mut rx: broadcast::Receiver<crate::terminal::output_hub::OutputChunk>,
        hub: Arc<TerminalOutputHub>,
        writer: tokio::net::unix::OwnedWriteHalf,
    ) {
        let mut writer = BufWriter::new(writer);
        let mut last_seen_sequence: Option<u64> = None;

        loop {
            match rx.recv().await {
                Ok(chunk) => {
                    last_seen_sequence = Some(chunk.sequence);
                    let msg = DaemonStreamMessage::Output {
                        session_id: Cow::Borrowed(&session_id),
                        sequence: chunk.sequence,
                        data: Cow::Borrowed(&chunk.bytes),
                    };
                    let mut json = serde_json::to_string(&msg).unwrap();
                    json.push('\n');
                    if writer.write_all(json.as_bytes()).await.is_err() {
                        break;
                    }
                    if writer.flush().await.is_err() {
                        break;
                    }
                }
                Err(broadcast::error::RecvError::Lagged(_)) => {
                    // Re-subscribe with sequence after last_seen_sequence to recover replay gap
                    if let Some(att) = hub.subscribe_with_sequence(&session_id, last_seen_sequence)
                    {
                        rx = att.receiver;
                        if att.snapshot.history_end_sequence.is_some() {
                            last_seen_sequence = att.snapshot.history_end_sequence;
                        }
                        let msg = DaemonStreamMessage::Lagged {
                            session_id: Cow::Borrowed(&session_id),
                            start_sequence: att.snapshot.history_start_sequence,
                            end_sequence: att.snapshot.history_end_sequence,
                            gap: att.snapshot.gap,
                            history: Cow::Borrowed(&att.snapshot.history),
                        };
                        let mut json = serde_json::to_string(&msg).unwrap();
                        json.push('\n');
                        if writer.write_all(json.as_bytes()).await.is_err() {
                            break;
                        }
                        if writer.flush().await.is_err() {
                            break;
                        }
                    }
                }
                Err(broadcast::error::RecvError::Closed) => {
                    let msg = DaemonStreamMessage::Exit {
                        session_id: Cow::Borrowed(&session_id),
                        exit_code: None,
                    };
                    let mut json = serde_json::to_string(&msg).unwrap();
                    json.push('\n');
                    let _ = writer.write_all(json.as_bytes()).await;
                    let _ = writer.flush().await;
                    break;
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
