        let hub_clone = Arc::clone(&hub);
        let pump_handle = tokio::spawn(DaemonServer::pump_sequenced_stream(
            session_id.clone(),
            rx,
            hub_clone,
            server_write,
        ));

        // Trigger more output to produce a Lagged event on the slow subscriber
        for i in 100..200 {
